const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0];
const cost = [];
for (let i = 0; i < n; i++) cost.push(tok.slice(1 + i * n, 1 + (i + 1) * n));
const full = (1 << n) - 1;
const dp = new Array(full + 1).fill(Infinity);
dp[0] = 0;
for (let mask = 0; mask <= full; mask++) {
  let i = 0;
  for (let t = mask; t; t &= t - 1) i++;
  if (i === n) continue;
  for (let j = 0; j < n; j++) {
    if (!((mask >> j) & 1)) {
      const nm = mask | (1 << j);
      if (dp[mask] + cost[i][j] < dp[nm]) dp[nm] = dp[mask] + cost[i][j];
    }
  }
}
console.log(dp[full]);

solutions.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[][] cost = new long[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) cost[i][j] = sc.nextLong();
        int full = (1 << n) - 1;
        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[full + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 0; mask <= full; mask++) {
            int i = Integer.bitCount(mask);
            if (i == n) continue;
            for (int j = 0; j < n; j++) {
                if ((mask >> j & 1) == 0) {
                    int nm = mask | (1 << j);
                    dp[nm] = Math.min(dp[nm], dp[mask] + cost[i][j]);
                }
            }
        }
        System.out.println(dp[full]);
    }
}

