#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<vector<long long>> cost(n, vector<long long>(n));
    for (auto& row : cost) for (auto& x : row) scanf("%lld", &x);
    int full = (1 << n) - 1;
    const long long INF = LLONG_MAX / 4;
    vector<long long> dp(full + 1, INF);
    dp[0] = 0;
    for (int mask = 0; mask <= full; mask++) {
        int i = __builtin_popcount(mask);
        if (i == n) continue;
        for (int j = 0; j < n; j++) {
            if (!(mask >> j & 1)) {
                int nm = mask | (1 << j);
                dp[nm] = min(dp[nm], dp[mask] + cost[i][j]);
            }
        }
    }
    printf("%lld\n", dp[full]);
    return 0;
}
